script:
(function () {
  'use strict';
  // 457(b) projection. Each year you defer contrib% of pay and the employer may add a % of pay; for a
  // 457(b) the employer money counts toward the same annual limit. Deposits go in monthly and compound
  // monthly at the equivalent of the annual return.
  // Limits (when applied): basic limit; governmental plans add the age 50+ (or ages 60-63) catch-up.
  // Special 457(b) catch-up (IRC 457(b)(3)) in the last three taxable years ending before the year you
  // reach the plan's normal retirement age: up to the lesser of twice the basic limit or the basic limit
  // plus the basic limit left unused in earlier years. A participant can't use both catch-ups in the same
  // year (IRC 457(e)(18), 414(v)(6)(C)), so the larger one applies. Unused basic limit in the projection
  // years before the special window is added to the unused amount you enter.
  // Checked in Node (fake DOM, whole script): $500/month at 7% for 30 years = $584,726 (annuity formula,
  // matches 401k-calculator); caps $24,500 (age 40), $32,500 (governmental, 55), $35,750 (61), $24,500
  // (tax-exempt employer, 55); special catch-up with normal retirement age 65 applies at ages 62-64 only:
  // $49,000 each year with $100,000 unused ($73,500 extra in total); with $10,000 unused the ages 60-63
  // catch-up ($35,750) wins at 62-63 and the special $34,500 at 64; a 5% employer contribution on
  // $100,000 leaves you $19,500 of the $24,500 limit.
  // ---- 2026 IRS limits (IRS Notice 2025-67: 457(e)(15) and 414(v) amounts, tax year 2026) ------------
  var LIMITS = {
    year: 2026,
    basic: 24500,         // 457(e)(15) limit on all deferrals, employee plus employer
    catchUp50: 8000,      // 414(v) catch-up, age 50 or older, governmental 457(b) only
    catchUp60to63: 11250, // SECURE 2.0 higher catch-up, ages 60-63, governmental 457(b) only
    specialMultiple: 2,   // special 457(b) catch-up: up to twice the basic limit
    specialYears: 3       // the 3 taxable years before the year of normal retirement age
  };
  // ----------------------------------------------------------------------------------------------------

  function catchUpFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.catchUp50;
    return 0;
  }

  // p: age, retireAge, salary, raise, balance, contrib, employer, rate, inflation (decimals), gov (bool),
  //    applyLimits, special (bool), nra, unused.
  function project(p) {
    var years = p.retireAge - p.age, mRate = Math.pow(1 + p.rate, 1 / 12) - 1;
    var bal = p.balance, salary = p.salary, totYou = 0, totEr = 0, totSpecial = 0, pool = p.unused;
    var rows = [], capped = false;
    for (var y = 0; y < years; y++) {
      var a = p.age + y, er = salary * p.employer, you = salary * p.contrib, kind = 'Basic', limit = Infinity;
      if (p.applyLimits) {
        var ageLimit = LIMITS.basic + (p.gov ? catchUpFor(a) : 0);
        limit = ageLimit;
        if (p.gov && catchUpFor(a) > 0) kind = a >= 60 && a <= 63 ? 'Age 60\u201363' : 'Age 50+';
        var inWindow = p.special && a >= p.nra - LIMITS.specialYears && a < p.nra;
        if (inWindow) {
          var specialLimit = Math.min(LIMITS.specialMultiple * LIMITS.basic, LIMITS.basic + pool);
          if (specialLimit > ageLimit) { limit = specialLimit; kind = 'Special 457'; }
        }
        if (er > LIMITS.basic) { er = LIMITS.basic; capped = true; }
        if (you > limit - er) { you = Math.max(0, limit - er); capped = true; }
      }
      if (you + er > salary) you = Math.max(0, salary - er); // deferrals can't exceed pay
      var total = you + er, specialUsed = kind === 'Special 457' ? Math.max(0, total - LIMITS.basic) : 0;
      if (p.applyLimits) pool = Math.max(0, pool + Math.max(0, LIMITS.basic - total) - specialUsed);
      totSpecial += specialUsed;
      var dep = total / 12;
      for (var m = 0; m < 12; m++) bal = bal * (1 + mRate) + dep;
      totYou += you; totEr += er;
      rows.push({ age: a, salary: salary, you: you, er: er, kind: p.applyLimits ? kind : '–', limit: limit, balance: bal });
      salary *= 1 + p.raise;
    }
    return { balance: bal, real: bal / Math.pow(1 + p.inflation, years), you: totYou, er: totEr,
             growth: bal - p.balance - totYou - totEr, special: totSpecial, rows: rows, capped: capped };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var age = num('fsAge'), retireAge = num('fsRetireAge'), salary = num('fsSalary'), raise = num('fsRaise'),
        balance = num('fsBalance'), contrib = num('fsContrib'), employer = num('fsEmployer'), rate = num('fsRate'),
        inflation = num('fsInflation'), nra = num('fsNra'), unused = num('fsUnused'),
        gov = document.getElementById('fsType').value === 'gov',
        applyLimits = document.getElementById('fsLimits').checked, special = document.getElementById('fsSpecial').checked;
    document.getElementById('fsSpecialFields').hidden = !special;
    document.getElementById('fsGovNote').hidden = !gov;
    document.getElementById('fsNonGovNote').hidden = gov;
    var error = document.getElementById('fsError');
    var bad = [age, retireAge, salary, raise, balance, contrib, employer, rate, inflation].some(isNaN) ||
              age !== Math.round(age) || retireAge !== Math.round(retireAge) || age < 16 || age > 99 ||
              retireAge <= age || retireAge > 100 || salary < 0 || balance < 0 || raise < 0 || raise > 20 ||
              contrib < 0 || contrib > 100 || employer < 0 || employer > 100 || rate < 0 || rate > 30 ||
              inflation < 0 || inflation > 20 ||
              (special && (isNaN(nra) || isNaN(unused) || nra !== Math.round(nra) || nra < 40 || nra > 72 || unused < 0));
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter whole-number ages from 16 to 99 with retirement above your age (up to 100), non-negative amounts, ' +
                          'percentages from 0 to 100, a return up to 30% and inflation up to 20%' +
                          (special ? ', plus a normal retirement age from 40 to 72.' : '.');
      return;
    }
    var r = project({ age: age, retireAge: retireAge, salary: salary, raise: raise / 100, balance: balance,
                      contrib: contrib / 100, employer: employer / 100, rate: rate / 100, inflation: inflation / 100,
                      gov: gov, applyLimits: applyLimits, special: special, nra: nra, unused: unused });
    set('fsFuture', fmt(r.balance)); set('fsReal', fmt(r.real)); set('fsYou', fmt(r.you)); set('fsEr', fmt(r.er));
    set('fsGrowth', fmt(r.growth)); set('fsSpecialTotal', fmt(r.special));
    set('fsRetireLabel', 'Balance at age ' + retireAge);
    var first = r.rows[0];
    set('fsFirstYear', 'First year: you put in ' + fmt(first.you) + (first.er > 0 ? ' and your employer adds ' + fmt(first.er) : '') +
        (applyLimits ? '. Your ' + LIMITS.year + ' limit, employer money included, is ' + fmt(first.limit) + '.' : '.'));
    var capEl = document.getElementById('fsCapped');
    capEl.hidden = !r.capped;
    if (r.capped) set('fsCapped', 'In some years contributions are reduced to stay within the ' + LIMITS.year + ' IRS limits shown below.');
    var win = document.getElementById('fsWindow');
    var hasWindow = special && applyLimits;
    win.hidden = !hasWindow;
    if (hasWindow) set('fsWindow', 'Special catch-up years: ages ' + (nra - LIMITS.specialYears) + ' to ' + (nra - 1) +
        (gov ? '. In each of those years the larger of the special catch-up and the age 50+ catch-up applies.' : '.'));
    var body = document.getElementById('fsSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, fmt(row.salary), fmt(row.you), fmt(row.er), row.kind, fmt(row.balance)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    set('fsLimitBasic', fmt(LIMITS.basic)); set('fsLimitCatch50', fmt(LIMITS.catchUp50));
    set('fsLimitCatch60', fmt(LIMITS.catchUp60to63)); set('fsLimitSpecial', 'Up to ' + fmt(LIMITS.specialMultiple * LIMITS.basic));
    var form = document.getElementById('fsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
